+        if (month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
+                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15)) {
+            return true;
+        }
+        return isEasterWeek(date);
+    }
+
+    private static boolean isEasterWeek(LocalDate date) {
+        int year = date.getYear();
+        int month = date.getMonthValue();
+        int dayOfMonth = date.getDayOfMonth();
+
+        if (year == 2027 && month == 3) {
+            return dayOfMonth >= 21 && dayOfMonth <= 28;
+        }
+        if (year == 2028 && month == 4) {
+            return dayOfMonth >= 9 && dayOfMonth <= 16;
+        }
+        return false;
     }

     static BigDecimal cents(BigDecimal value) {
